def count_polynomials():
    count = 0
    for a3 in range(2013):
        if a3 % 61 == 0:
            for a1 in range(2013):
                if a1 % 61 != 0:
                    # Modulo 11 condition
                    cond11 = (a3 % 11 == 0 and a1 % 11 != 0) or (a3 % 11 != 0 and a1 % 11 == 0)
                    if cond11:
                        # Modulo 3 condition
                        if (a1 + a3) % 3 != 0:
                            count += 1
    return count

print(count_polynomials())
